window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-355cc842e535ed3f"]={"versions": [{"id": "FIG-355cc842e535ed3f", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm (Subdiagramm / Kontrollflussdiagramm) im Kontext des AUTOSAR E2E Library Profile 1 (E2E P01) Spezifikationsdokuments <code>AUTOSAR_PRS_E2EProtocol</code>. Es visualisiert den standardisierten Teilalgorithmus „Calculate CRC over Data ID and Data“, welcher von den Funktionen <code>E2E_P01Protect()</code>, <code>E2E_P01Forward()</code> und <code>E2E_P01Check()</code> zur Prüfsummenbildung über den Nutzdatenstrom aufgerufen wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Initialer Knoten & Endknoten</strong>: Start- und Endpunkt der sequenziellen Prüfsummenberechnung.</li>\n<li><strong>Aktionen / Funktionsaufrufe</strong>:</li>\n<li><code>CRC = E2E_P01_getDataIDCRC(Config-&gt;DataID, Config-&gt;DataIDMode)</code>: Initialisierung des CRC-Wertes durch Berechnung/Nachschlagen des CRC über die Data ID (gekennzeichnet als Sub-Aktivität/Call-Behavior mit Schlingen-Symbol).</li>\n<li><code>CRC = Crc_CalculateCRC8 (Data, (Config-&gt;CRCOffset / 8), CRC, FALSE)</code>: Berechnung des CRC-8 über den Bytebereich vor der CRC-Position mittels AUTOSAR CRC-Bibliothek.</li>\n<li><code>CRC = Crc_CalculateCRC8 (&amp; Data[Config-&gt;CRCOffset/8 + 1], (Config-&gt;DataLength / 8 - Config-&gt;CRCOffset / 8 - 1), CRC, FALSE)</code>: Berechnung des CRC-8 über den Bytebereich nach der CRC-Position.</li>\n<li><code>CRC = CRC ^ 0xFF</code>: Abschließende Negierung/XOR-Operation mit <code>0xFF</code> durch die E2E-Bibliothek.</li>\n<li><strong>Entscheidungsknoten (Decision Points / Branches & Merges)</strong>:</li>\n<li>Guard <code>[Config-&gt;CRCOffset &gt;= 8]</code>: Verzweigung <code>[TRUE]</code> / <code>[FALSE]</code> zur Überprüfung, ob Bytes vor dem CRC-Feld existieren.</li>\n<li>Guard <code>[Config-&gt;CRCOffset / 8 &lt; (Config-&gt;DataLength / 8) - 1]</code>: Verzweigung <code>[TRUE]</code> / <code>[FALSE]</code> zur Überprüfung, ob Bytes nach dem CRC-Feld existieren.</li>\n<li><strong>Datenstrukturen / Variablen</strong>:</li>\n<li><code>Config</code>: Konfigurationsstruktur mit den Feldern <code>DataID</code>, <code>DataIDMode</code>, <code>CRCOffset</code> (in Bit) und <code>DataLength</code> (in Bit).</li>\n<li><code>Data</code>: Byte-Array der Nutzdaten.</li>\n<li><code>CRC</code>: Lokale 8-Bit-CRC-Variable.</li>\n<li><strong>Kommentare / Annotationen</strong>: Erläuternde Notizen zur Behandlung der internen Initial- und Final-XOR-Operationen (<code>0xFF</code>) der aufgerufenen <code>Crc_CalculateCRC8</code>-Bibliotheksfunktion.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Start</strong>: Eintritt in die Aktivität am Initialknoten.</li>\n<li><strong>Data-ID-CRC</strong>: Ausführung von <code>E2E_P01_getDataIDCRC(Config-&gt;DataID, Config-&gt;DataIDMode)</code>, liefert den Startwert für <code>CRC</code>.</li>\n<li><strong>Prüfung Vorbereich</strong>: Auswertung der Bedingung <code>Config-&gt;CRCOffset &gt;= 8</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Falls <code>[TRUE]</code>: Ausführung von <code>Crc_CalculateCRC8 (Data, (Config-&gt;CRCOffset / 8), CRC, FALSE)</code>. Das Ergebnis aktualisiert <code>CRC</code>.</li>\n<li>Falls <code>[FALSE]</code>: Umgehung der Berechnung des Vorbereichs direkt zum Merge-Knoten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Prüfung Nachbereich</strong>: Auswertung der Bedingung <code>Config-&gt;CRCOffset / 8 &lt; (Config-&gt;DataLength / 8) - 1</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Falls <code>[TRUE]</code>: Ausführung von <code>Crc_CalculateCRC8 (&amp; Data[Config-&gt;CRCOffset/8 + 1], (Config-&gt;DataLength / 8 - Config-&gt;CRCOffset / 8 - 1), CRC, FALSE)</code>. Das Ergebnis aktualisiert <code>CRC</code>.</li>\n<li>Falls <code>[FALSE]</code>: Umgehung der Berechnung des Nachbereichs direkt zum Merge-Knoten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschluss-XOR</strong>: Ausführung von <code>CRC = CRC ^ 0xFF</code>.</li>\n<li><strong>Ende</strong>: Erreichen des Aktivitätsendknotens mit dem final berechneten CRC-Wert.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Diagramm definiert das normative Berechnungsverfahren zur Auslassung des eigenen CRC-Byte-Feldes im Datenstrom bei E2E Profile 1.</li>\n<li>Da <code>CRCOffset</code> und <code>DataLength</code> in Bit spezifiziert sind, erfolgt die Segmentierung byte-basiert (<code>/ 8</code>).</li>\n<li>Wie in den Kommentaren spezifiziert, heben sich das Final-XOR des vorhergehenden Aufrufs von <code>Crc_CalculateCRC8</code> und das Initial-XOR des nachfolgenden Aufrufs gegenseitig auf (<code>CRC ^ 0xFF ^ 0xFF = CRC</code>), da <code>IsFirstCall = FALSE</code> übergeben wird.</li>\n<li>Zur Kompensation des abschließenden <code>0xFF</code>-XOR des letzten <code>Crc_CalculateCRC8</code>-Aufrufs muss die E2E-Bibliothek abschließend zwingend <code>CRC = CRC ^ 0xFF</code> ausführen. Liegt weder ein Vor- noch ein Nachbereich vor (z. B. 1-Byte-Datenlänge nur mit CRC), negiert das abschließende XOR den von <code>E2E_P01_getDataIDCRC</code> ermittelten Wert.</li>\n</ul>"}, {"id": "FIG-7c2a3f2b4b1292a5", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm (Subdiagramm / Kontrollflussdiagramm) im Kontext des AUTOSAR E2E Library Profile 1 (E2E P01) Spezifikationsdokuments <code>AUTOSAR_PRS_E2EProtocol</code>. Es visualisiert den standardisierten Teilalgorithmus „Calculate CRC over Data ID and Data“, welcher von den Funktionen <code>E2E_P01Protect()</code>, <code>E2E_P01Forward()</code> und <code>E2E_P01Check()</code> zur Prüfsummenbildung über den Nutzdatenstrom aufgerufen wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Initialer Knoten & Endknoten</strong>: Start- und Endpunkt der sequenziellen Prüfsummenberechnung.</li>\n<li><strong>Aktionen / Funktionsaufrufe</strong>:</li>\n<li><code>CRC = E2E_P01_getDataIDCRC(Config-&gt;DataID, Config-&gt;DataIDMode)</code>: Initialisierung des CRC-Wertes durch Berechnung/Nachschlagen des CRC über die Data ID (gekennzeichnet als Sub-Aktivität/Call-Behavior mit Schlingen-Symbol).</li>\n<li><code>CRC = Crc_CalculateCRC8 (Data, (Config-&gt;CRCOffset / 8), CRC, FALSE)</code>: Berechnung des CRC-8 über den Bytebereich vor der CRC-Position mittels AUTOSAR CRC-Bibliothek.</li>\n<li><code>CRC = Crc_CalculateCRC8 (&amp; Data[Config-&gt;CRCOffset/8 + 1], (Config-&gt;DataLength / 8 - Config-&gt;CRCOffset / 8 - 1), CRC, FALSE)</code>: Berechnung des CRC-8 über den Bytebereich nach der CRC-Position.</li>\n<li><code>CRC = CRC ^ 0xFF</code>: Abschließende Negierung/XOR-Operation mit <code>0xFF</code> durch die E2E-Bibliothek.</li>\n<li><strong>Entscheidungsknoten (Decision Points / Branches & Merges)</strong>:</li>\n<li>Guard <code>[Config-&gt;CRCOffset &gt;= 8]</code>: Verzweigung <code>[TRUE]</code> / <code>[FALSE]</code> zur Überprüfung, ob Bytes vor dem CRC-Feld existieren.</li>\n<li>Guard <code>[Config-&gt;CRCOffset / 8 &lt; (Config-&gt;DataLength / 8) - 1]</code>: Verzweigung <code>[TRUE]</code> / <code>[FALSE]</code> zur Überprüfung, ob Bytes nach dem CRC-Feld existieren.</li>\n<li><strong>Datenstrukturen / Variablen</strong>:</li>\n<li><code>Config</code>: Konfigurationsstruktur mit den Feldern <code>DataID</code>, <code>DataIDMode</code>, <code>CRCOffset</code> (in Bit) und <code>DataLength</code> (in Bit).</li>\n<li><code>Data</code>: Byte-Array der Nutzdaten.</li>\n<li><code>CRC</code>: Lokale 8-Bit-CRC-Variable.</li>\n<li><strong>Kommentare / Annotationen</strong>: Erläuternde Notizen zur Behandlung der internen Initial- und Final-XOR-Operationen (<code>0xFF</code>) der aufgerufenen <code>Crc_CalculateCRC8</code>-Bibliotheksfunktion.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Start</strong>: Eintritt in die Aktivität am Initialknoten.</li>\n<li><strong>Data-ID-CRC</strong>: Ausführung von <code>E2E_P01_getDataIDCRC(Config-&gt;DataID, Config-&gt;DataIDMode)</code>, liefert den Startwert für <code>CRC</code>.</li>\n<li><strong>Prüfung Vorbereich</strong>: Auswertung der Bedingung <code>Config-&gt;CRCOffset &gt;= 8</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Falls <code>[TRUE]</code>: Ausführung von <code>Crc_CalculateCRC8 (Data, (Config-&gt;CRCOffset / 8), CRC, FALSE)</code>. Das Ergebnis aktualisiert <code>CRC</code>.</li>\n<li>Falls <code>[FALSE]</code>: Umgehung der Berechnung des Vorbereichs direkt zum Merge-Knoten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Prüfung Nachbereich</strong>: Auswertung der Bedingung <code>Config-&gt;CRCOffset / 8 &lt; (Config-&gt;DataLength / 8) - 1</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Falls <code>[TRUE]</code>: Ausführung von <code>Crc_CalculateCRC8 (&amp; Data[Config-&gt;CRCOffset/8 + 1], (Config-&gt;DataLength / 8 - Config-&gt;CRCOffset / 8 - 1), CRC, FALSE)</code>. Das Ergebnis aktualisiert <code>CRC</code>.</li>\n<li>Falls <code>[FALSE]</code>: Umgehung der Berechnung des Nachbereichs direkt zum Merge-Knoten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschluss-XOR</strong>: Ausführung von <code>CRC = CRC ^ 0xFF</code>.</li>\n<li><strong>Ende</strong>: Erreichen des Aktivitätsendknotens mit dem final berechneten CRC-Wert.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Diagramm definiert das normative Berechnungsverfahren zur Auslassung des eigenen CRC-Byte-Feldes im Datenstrom bei E2E Profile 1.</li>\n<li>Da <code>CRCOffset</code> und <code>DataLength</code> in Bit spezifiziert sind, erfolgt die Segmentierung byte-basiert (<code>/ 8</code>).</li>\n<li>Wie in den Kommentaren spezifiziert, heben sich das Final-XOR des vorhergehenden Aufrufs von <code>Crc_CalculateCRC8</code> und das Initial-XOR des nachfolgenden Aufrufs gegenseitig auf (<code>CRC ^ 0xFF ^ 0xFF = CRC</code>), da <code>IsFirstCall = FALSE</code> übergeben wird.</li>\n<li>Zur Kompensation des abschließenden <code>0xFF</code>-XOR des letzten <code>Crc_CalculateCRC8</code>-Aufrufs muss die E2E-Bibliothek abschließend zwingend <code>CRC = CRC ^ 0xFF</code> ausführen. Liegt weder ein Vor- noch ein Nachbereich vor (z. B. 1-Byte-Datenlänge nur mit CRC), negiert das abschließende XOR den von <code>E2E_P01_getDataIDCRC</code> ermittelten Wert.</li>\n</ul>"}], "trans": [{"from": "FIG-355cc842e535ed3f", "to": "FIG-7c2a3f2b4b1292a5", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
